import json
report=json.load(open('/root/trivy_report.json', encoding='utf-8'))
findings=[]
for result in report.get('Results',[]):
  for vuln in result.get('Vulnerabilities') or []:
    if vuln.get('Severity') in {'HIGH','CRITICAL'}:
      cvss=vuln.get('CVSS') or {}
      score=next((cvss[key].get('V3Score') for key in ('nvd','ghsa','redhat') if isinstance(cvss.get(key),dict) and cvss[key].get('V3Score') is not None),'N/A')
      findings.append((vuln.get('PkgName'),vuln.get('InstalledVersion'),vuln.get('VulnerabilityID'),vuln.get('Severity'),score,vuln.get('FixedVersion') or 'N/A',vuln.get('Title') or vuln.get('Description') or 'N/A',vuln.get('PrimaryURL') or 'N/A'))
for item in sorted(findings, key=lambda row:(row[0].lower(),row[2])):
  print('\t'.join(map(str,item)))
print('COUNT',len(findings))
